mapper.sql:
cp.marketplace = #{marketplace}
AND cp.title IS NOT NULL
AND (
    cp.source LIKE '%新品%'
    OR LOWER(cp.source) LIKE '%new%'
)

    AND cp.month = #{month}


    AND cp.effective_week_tag = #{effectiveWeekTag}


    AND cp.bsr_id = #{bsrId}


    AND cp.node_id = #{nodeId}

AND cp.price BETWEEN #{priceMin} AND #{priceMax}
AND cp.weight_g IS NOT NULL
AND cp.weight_g < #{weightMax}
AND cp.listing_days IS NOT NULL
AND cp.listing_days < #{listingDaysMax}
AND (
    (cp.listing_days <= 30 AND cp.units IS NOT NULL AND cp.units >= #{sales30})
    OR (cp.listing_days <= 60 AND cp.units IS NOT NULL AND cp.units >= #{sales60})
    OR (cp.listing_days <= 90 AND cp.units IS NOT NULL AND cp.units >= #{sales90})
    OR (cp.bsr IS NOT NULL AND cp.bsr > 0 AND cp.bsr < #{bsrMax})
)

dz.marketplace = #{marketplace}
AND dz.asin IS NOT NULL
AND dz.title IS NOT NULL

    AND dz.month = #{month}


    AND dz.batch_date = #{batchDate}


    AND dz.bsr_id = #{bsrId}


    AND dz.node_id = #{nodeId}
